KG42.register("nodes-612af49cb3a8a6d9307f8027",{"id":"COMP-62155e4e7998a74f","code":"BID013","label":"Submission of minimum time-specific regulation energy relative to a baseline","definition":"Before the daily configuration algorithm is executed, the DSO submits to SESP the time-differentiated demand D_t^{DSO}∈ℝ, representing the active-power quantity change relative to the minimum requirement of the forecast baseline, in kWh/period; positive values request upward adjustment and negative values request downward adjustment, determining T^{+} and T^{-}, respectively.","layer":"L3","template_code":"SRP","concept_id":"bidding.demand","concept_ids":["bidding.demand"],"identity_dimensions":{"identity_fields":["Object: time-differentiated flexibility service demand","Core relation: submit a minimum active-power quantity change requirement relative to the forecast baseline","Output: the direction-signed demand parameter D_t^{DSO} and the corresponding set of request periods"]},"exclusions":["Requesting party DSO, receiving party SESP","The request covers the entire operating day and is sent before daily configuration","A positive sign indicates upward adjustment; a negative sign indicates downward adjustment","When receiving the request, SESP does not have grid state information"],"members":[{"id":"21-dso_flexibility_optimization::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"The requested quantity specifies the minimum required active-energy variation relative to the forecasted baseline. Positive quantities denote upward regulation and negative quantities denote downward regulation; the per-period request is expressed in kW h/period. Scope: DSO upward and downward regulation requests in the SESP-operated local flexibility market, for each requested period.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"DSO upward and downward regulation requests in the SESP-operated local flexibility market, for each requested period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-ev33","v141-b-g04-e01"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C001","21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"0ebeda885fe6002a799a1de662a79a4f220b5f8dac7b3f64f5bfea595cbca095","paper":"21-dso_flexibility_optimization","rule_ref":"21-dso_flexibility_optimization::v141-c-R002","node_id":"bidding.demand","function":"bidding.demand","unit_id":"21-dso_flexibility_optimization::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":true},{"id":"21-dso_flexibility_optimization::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"The DSO's requested flexibility supplies the input for determining local resource allocations over the operation day. Scope: SESP scheduling of local flexible resources for the operation day. The requested upward active-energy variation imposes a minimum on the net upward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Upward-regulation constraints in the local flexibility allocation problem. Condition: During upward-regulation periods with a positive DSO request. The requested downward active-energy variation imposes a minimum on the magnitude of net downward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Downward-regulation constraints in the local flexibility allocation problem. Condition: During downward-regulation periods with a negative DSO request. The DSO sends its flexibility needs before the SESP executes the daily local allocation algorithm. Scope: Daily allocation sequence described for the case study. The SESP, acting as the local market coordinator, determines which flexible resources are allocated to meet the DSO request. Scope: SESP-operated local flexibility market serving DSO power-quality requirements. Local allocation minimizes the SESP's operating cost of meeting the DSO request over the following periods, using flexibility costs predefined in SESP-community member contracts. Scope: Objective of the local flexibility allocation problem. Local flexibility allocation is restricted to providing flexibility to the DSO. Scope: Service scope of the presented local flexibility market. DSO needs receive maximum priority to avoid over-voltages or transformer over-loads; prosumer or aggregator priorities are not considered. Scope: Local allocation priorities under the Traffic Light Concept used in the formulation. Condition: During yellow light situations. Allocation must respect the contracted times during which the offered flexibility can be used. Scope: Availability restrictions on contracted flexibility used in local allocation. Condition: When allocating resources whose flexibility contracts specify permitted usage times. Allocated generation curtailment is nonnegative and cannot exceed the forecasted generation. Scope: Reducible-generator feasibility constraints in local allocation. Condition: For reducible generators in each scheduling period. Allocation permits only switching these generators on or off; intermediate production setpoints are unavailable. Scope: Disconnectable-generator feasibility restrictions in local allocation. Condition: For disconnectable generators. Battery allocations must respect per-period charging and discharging limits and maximum storage capacity, with charging and discharging efficiencies included in state-of-charge accounting. Scope: Battery feasibility constraints in local allocation. Condition: When allocating battery charging or discharging. The allocation schedule must either maintain the disconnection or reconnect the load in the current period. Scope: Continuity of curtailable disconnectable load schedules in local allocation. Condition: After a load was disconnected or remained disconnected in the preceding period. Allocation schedules must respect the maximum number of disconnection orders per day, the minimum resting time between disconnections and the maximum disconnection duration, as applicable. Scope: Configured operating bounds for curtailable disconnectable loads in local allocation. Condition: When the corresponding disconnection-count, resting-time or duration bounds are specified. Curtailable disconnectable loads cannot supply downward regulation because they cannot consume outside their baseline. Scope: Directional availability of curtailable disconnectable loads in the allocation model. Condition: When allocating downward regulation. The scheduled consumption profile must fit the permitted shifting window. Postponement preserves the consumption profile, cannot split it, and allows only one shift per shifting period. Scope: Shiftable-profile load feasibility in local allocation. Condition: For each appliance and its permitted shifting periods, including when the profile is not postponed. The case-study allocation includes a terminal constraint restoring stored energy to its initial amount at the end of the simulation horizon. Scope: Battery terminal-energy restriction in the simulated case study.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Availability restrictions on contracted flexibility used in local allocation. | Battery feasibility constraints in local allocation. | Battery terminal-energy restriction in the simulated case study. | Configured operating bounds for curtailable disconnectable loads in local allocation. | Continuity of curtailable disconnectable load schedules in local allocation. | Daily allocation sequence described for the case study. | Directional availability of curtailable disconnectable loads in the allocation model. | Disconnectable-generator feasibility restrictions in local allocation. | Downward-regulation constraints in the local flexibility allocation problem. | Local allocation priorities under the Traffic Light Concept used in the formulation. | Objective of the local flexibility allocation problem. | Reducible-generator feasibility constraints in local allocation. | SESP scheduling of local flexible resources for the operation day. | SESP-operated local flexibility market serving DSO power-quality requirements. | Service scope of the presented local flexibility market. | Shiftable-profile load feasibility in local allocation. | Upward-regulation constraints in the local flexibility allocation problem.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-001","v141-b-g01-ev-004","v141-b-g01-ev-006","v141-b-g01-ev-007","v141-b-g01-ev-010","v141-b-g01-ev-013","v141-b-g02-ev05","v141-b-g02-ev10","v141-b-g02-ev11","v141-b-g02-ev13","v141-b-g02-ev15","v141-b-g02-ev20","v141-b-g02-ev21","v141-b-g02-ev22","v141-b-g02-ev23","v141-b-g02-ev25","v141-b-g02-ev29","v141-b-g02-ev33","v141-b-g02-ev34","v141-b-g02-ev36","v141-b-g02-ev37","v141-b-g03-E13","v141-b-g03-E15","v141-b-g04-e03"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C001","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C002","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C003","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C004"],"decision_anchor":"clearing.local","source_rule_sha256":"13aaf9ab97f39a93298400dacbf1f3833b654760ae93a47ef02ed6c7d66f1361","paper":"21-dso_flexibility_optimization","rule_ref":"21-dso_flexibility_optimization::v141-c-R003","node_id":"bidding.demand","function":"bidding.demand","unit_id":"21-dso_flexibility_optimization::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false},{"id":"21-dso_flexibility_optimization::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"The SESP, acting as aggregator, receives DSO flexibility requests specifying minimum active-energy variations relative to the forecast baseline, without knowing grid-status information. Scope: DSO upward- and downward-regulation requests in the SESP-operated local flexibility market. The SESP's coordination of corrective actions must give DSO needs maximum priority to avoid over-voltages or transformer over-loads. Scope: SESP coordination of corrective actions in the local flexibility market. Condition: During a DSO-designated yellow-light grid situation. The SESP may send direct control signals overriding local household energy-management decisions. Scope: SESP control authority over local household resource decisions. Condition: During a grid-constrained yellow-light situation. The SESP's forecast must have DSO approval before it is used as the baseline scenario. Scope: Use of SESP forecasts as the flexibility-market baseline. Condition: When a consumption or generation forecast for a flexible asset is to be used as the baseline scenario.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"DSO upward- and downward-regulation requests in the SESP-operated local flexibility market. | SESP control authority over local household resource decisions. | SESP coordination of corrective actions in the local flexibility market. | Use of SESP forecasts as the flexibility-market baseline.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-001","v141-b-g01-ev-003","v141-b-g01-ev-004","v141-b-g01-ev-011","v141-b-g01-ev-014","v141-b-g02-ev33"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"f0a3f24e00e9c27d1e767402691fddd0233d7645925a90b115075bfc3ea2381f","paper":"21-dso_flexibility_optimization","rule_ref":"21-dso_flexibility_optimization::v141-c-R004","node_id":"bidding.demand","function":"bidding.demand","unit_id":"21-dso_flexibility_optimization::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["21-dso_flexibility_optimization"],"evidence":[{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R002","quote":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g04-e01","location":{"location_id":"src-58f2111926-p12-c1r3__v141-a-M01-clearing","page":12,"printed_page":null,"section":null,"anchor_text":"The integration of DER into the distribution grids can lead to th technical issues aﬀecting the powe","equation_id":null,"figure_id":null,"table_id":"Table A.2/Table A.3","image_ref":"pages/page-12.png","occurrence_role":"definition"},"source_text":"Table A.2\nSets and subsets.\nT Set of periods, indexed by t\nT^{+} Subset of periods with DSO requests for upward regulation\nT^{-} Subset of periods with DSO requests for downward regulation\nK Set of non-buffered flexible loads, indexed by k\nK^{CD} Subset of flexible load units of type curtailable disconnectable\nK^{SP} Subset of flexible load units of type shiftable profile\nC Set of shiftable load periods, indexed by c. It depends on each k\nG Set of flexible distributed generators, indexed by g\nG^{r} Subset of reducible distributed generators\nG^{d} Subset of disconnectable distributed generators\nB Set of storage units, indexed by b\n\nTable A.3\nDSO parameter.\nD^{DSO}_{t} DSO request in the local flexibility market during period t [kW h/period]","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R002","quote":"Table A.2\nSets and subsets.\nT Set of periods, indexed by t\nT^{+} Subset of periods with DSO requests for upward regulation\nT^{-} Subset of periods with DSO requests for downward regulation\nK Set of non-buffered flexible loads, indexed by k\nK^{CD} Subset of flexible load units of type curtailable disconnectable\nK^{SP} Subset of flexible load units of type shiftable profile\nC Set of shiftable load periods, indexed by c. It depends on each k\nG Set of flexible distributed generators, indexed by g\nG^{r} Subset of reducible distributed generators\nG^{d} Subset of disconnectable distributed generators\nB Set of storage units, indexed by b\n\nTable A.3\nDSO parameter.\nD^{DSO}_{t} DSO request in the local flexibility market during period t [kW h/period]"},{"evidence_id":"v141-b-g02-ev34","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17), Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R002","quote":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons."},{"evidence_id":"v141-b-g01-ev-006","location":{"location_id":"src-58f2111926-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"be In order to run these markets, local traders need the SESP Platform for or sending information, t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The flexibility market is executed in hours ahead time frames and its time schedule is shown in the Fig. 2. At the end of the day-before the operation, the DSO determines the flexibility need for the entire operation day. Based on the DSO request, the SESP can schedule flexible resources optimally considering the entire operation day. In the EMPOWER Project, the LFM is executed at 11 p.m. and the period unit is quarter hour.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"The flexibility market is executed in hours ahead time frames and its time schedule is shown in the Fig. 2. At the end of the day-before the operation, the DSO determines the flexibility need for the entire operation day. Based on the DSO request, the SESP can schedule flexible resources optimally considering the entire operation day. In the EMPOWER Project, the LFM is executed at 11 p.m. and the period unit is quarter hour."},{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g02-ev34","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17), Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons."},{"evidence_id":"v141-b-g02-ev35","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"∑b ∈ B σbout,t + ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t )+ ∑k ∈ K SP (WkSP,t −ωk ,t )−∑g ∈ G r χ gGr,t − ∑g ∈ G d χ gGd,t −∑b ∈ B σbin,t ⩾ DtDSO      ∀ t ∈ T +  (17)","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"∑b ∈ B σbout,t + ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t )+ ∑k ∈ K SP (WkSP,t −ωk ,t )−∑g ∈ G r χ gGr,t − ∑g ∈ G d χ gGd,t −∑b ∈ B σbin,t ⩾ DtDSO      ∀ t ∈ T +  (17)"},{"evidence_id":"v141-b-g02-ev36","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"For each downward regulation period (t ∈ T − ), deﬁned as negative request ( DtDSO \u003c 0 ), the upward and downward ﬂexibility resources have negative and positive sign respectively in Eq. (18).\n∑g ∈ G r χ gGr,t + ∑g ∈ G d χ gGd,t + ∑b ∈ B σbin,t + ∑k ∈ K SP (ωk ,t −WkSP,t )−∑b ∈ B σbout,t − ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t ) ⩾−DtDSO      ∀ t ∈ T −  (18)","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"For each downward regulation period (t ∈ T − ), deﬁned as negative request ( DtDSO \u003c 0 ), the upward and downward ﬂexibility resources have negative and positive sign respectively in Eq. (18).\n∑g ∈ G r χ gGr,t + ∑g ∈ G d χ gGd,t + ∑b ∈ B σbin,t + ∑k ∈ K SP (ωk ,t −WkSP,t )−∑b ∈ B σbout,t − ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t ) ⩾−DtDSO      ∀ t ∈ T −  (18)"},{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-58f2111926-p10-c1r3__v141-a-M01-clearing","page":10,"printed_page":null,"section":"5.1 Scenario description","anchor_text":"proﬁle (W k ,t + Wk ,t ) with a maximum demand of 11.15 kW h during m period 48. Generation forecast","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"example"},"source_text":"The DDSO is the DSO request for the operation day. In the case study, the available flexibility is larger than the DSO need for all periods. Therefore, SESP has to execute the LFM to allocate the cheapest flexible resources considering the problem constraints. If the SESP has not enough resources, it cannot attend the DSO request completely. ... the time horizon is one day. The SESP algorithm is executed once per day before the operation day begins. Previously, the DSO has sent its flexibility needs.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R003","quote":"The DDSO is the DSO request for the operation day. In the case study, the available flexibility is larger than the DSO need for all periods. Therefore, SESP has to execute the LFM to allocate the cheapest flexible resources considering the problem constraints. If the SESP has not enough resources, it cannot attend the DSO request completely. ... the time horizon is one day. The SESP algorithm is executed once per day before the operation day begins. Previously, the DSO has sent its flexibility needs."},{"evidence_id":"v141-b-g01-ev-001","location":{"location_id":"src-58f2111926-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"be In order to run these markets, local traders need the SESP Platform for or sending information, t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"A local flexibility market (LFM) is an electricity trading platform to sell and buy flexibility in geographically limited areas like neighbourhoods and small towns. The SESP is the local market platform provider and community aggregator (AGR). At the same time, the SESP is a BRP from the regulatory point of view because it bids in wholesale markets. In order to run these markets, local traders need the SESP Platform for sending information, trading for flexibility, and scheduling actions.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R004","quote":"A local flexibility market (LFM) is an electricity trading platform to sell and buy flexibility in geographically limited areas like neighbourhoods and small towns. The SESP is the local market platform provider and community aggregator (AGR). At the same time, the SESP is a BRP from the regulatory point of view because it bids in wholesale markets. In order to run these markets, local traders need the SESP Platform for sending information, trading for flexibility, and scheduling actions."},{"evidence_id":"v141-b-g01-ev-003","location":{"location_id":"src-58f2111926-p02-c2r4__v141-a-M01-coordination","page":2,"printed_page":"882","section":"2.1. Centralized local flexibility market approaches","anchor_text":"on same distribution transformer have to be members of the same BRP and diﬀerent BRP could not be in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"In contrast  in  this work, AGR receives DSO requests without knowing grid status information to solve grid congestion problems in the daily basis. In order to attend its demands, AGR controls flexible assets using a market-based methodology.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R004","quote":"In contrast  in  this work, AGR receives DSO requests without knowing grid status information to solve grid congestion problems in the daily basis. In order to attend its demands, AGR controls flexible assets using a market-based methodology."},{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively.","paper":"21-dso_flexibility_optimization","rule_id":"v141-c-R004","quote":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."}],"candidate_only":true,"classification_subtypes":["signed_minimum_regulation_request"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L3-6266d09c69","secondary_families":[],"stage":"L3","ontological_kind":"signed_minimum_regulation_request"},"semantic_definition":{},"source_units":[{"unit_id":"21-dso_flexibility_optimization::v141-a-M01::bidding.demand","paper_id":"21-dso_flexibility_optimization","mechanism_id":"v141-a-M01","function":"bidding.demand","source_occurrences":[{"id":"21-dso_flexibility_optimization::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"The requested quantity specifies the minimum required active-energy variation relative to the forecasted baseline. Positive quantities denote upward regulation and negative quantities denote downward regulation; the per-period request is expressed in kW h/period. Scope: DSO upward and downward regulation requests in the SESP-operated local flexibility market, for each requested period.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"DSO upward and downward regulation requests in the SESP-operated local flexibility market, for each requested period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-ev33","v141-b-g04-e01"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C001","21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"0ebeda885fe6002a799a1de662a79a4f220b5f8dac7b3f64f5bfea595cbca095"},{"id":"21-dso_flexibility_optimization::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"The DSO's requested flexibility supplies the input for determining local resource allocations over the operation day. Scope: SESP scheduling of local flexible resources for the operation day. The requested upward active-energy variation imposes a minimum on the net upward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Upward-regulation constraints in the local flexibility allocation problem. Condition: During upward-regulation periods with a positive DSO request. The requested downward active-energy variation imposes a minimum on the magnitude of net downward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Downward-regulation constraints in the local flexibility allocation problem. Condition: During downward-regulation periods with a negative DSO request. The DSO sends its flexibility needs before the SESP executes the daily local allocation algorithm. Scope: Daily allocation sequence described for the case study. The SESP, acting as the local market coordinator, determines which flexible resources are allocated to meet the DSO request. Scope: SESP-operated local flexibility market serving DSO power-quality requirements. Local allocation minimizes the SESP's operating cost of meeting the DSO request over the following periods, using flexibility costs predefined in SESP-community member contracts. Scope: Objective of the local flexibility allocation problem. Local flexibility allocation is restricted to providing flexibility to the DSO. Scope: Service scope of the presented local flexibility market. DSO needs receive maximum priority to avoid over-voltages or transformer over-loads; prosumer or aggregator priorities are not considered. Scope: Local allocation priorities under the Traffic Light Concept used in the formulation. Condition: During yellow light situations. Allocation must respect the contracted times during which the offered flexibility can be used. Scope: Availability restrictions on contracted flexibility used in local allocation. Condition: When allocating resources whose flexibility contracts specify permitted usage times. Allocated generation curtailment is nonnegative and cannot exceed the forecasted generation. Scope: Reducible-generator feasibility constraints in local allocation. Condition: For reducible generators in each scheduling period. Allocation permits only switching these generators on or off; intermediate production setpoints are unavailable. Scope: Disconnectable-generator feasibility restrictions in local allocation. Condition: For disconnectable generators. Battery allocations must respect per-period charging and discharging limits and maximum storage capacity, with charging and discharging efficiencies included in state-of-charge accounting. Scope: Battery feasibility constraints in local allocation. Condition: When allocating battery charging or discharging. The allocation schedule must either maintain the disconnection or reconnect the load in the current period. Scope: Continuity of curtailable disconnectable load schedules in local allocation. Condition: After a load was disconnected or remained disconnected in the preceding period. Allocation schedules must respect the maximum number of disconnection orders per day, the minimum resting time between disconnections and the maximum disconnection duration, as applicable. Scope: Configured operating bounds for curtailable disconnectable loads in local allocation. Condition: When the corresponding disconnection-count, resting-time or duration bounds are specified. Curtailable disconnectable loads cannot supply downward regulation because they cannot consume outside their baseline. Scope: Directional availability of curtailable disconnectable loads in the allocation model. Condition: When allocating downward regulation. The scheduled consumption profile must fit the permitted shifting window. Postponement preserves the consumption profile, cannot split it, and allows only one shift per shifting period. Scope: Shiftable-profile load feasibility in local allocation. Condition: For each appliance and its permitted shifting periods, including when the profile is not postponed. The case-study allocation includes a terminal constraint restoring stored energy to its initial amount at the end of the simulation horizon. Scope: Battery terminal-energy restriction in the simulated case study.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Availability restrictions on contracted flexibility used in local allocation. | Battery feasibility constraints in local allocation. | Battery terminal-energy restriction in the simulated case study. | Configured operating bounds for curtailable disconnectable loads in local allocation. | Continuity of curtailable disconnectable load schedules in local allocation. | Daily allocation sequence described for the case study. | Directional availability of curtailable disconnectable loads in the allocation model. | Disconnectable-generator feasibility restrictions in local allocation. | Downward-regulation constraints in the local flexibility allocation problem. | Local allocation priorities under the Traffic Light Concept used in the formulation. | Objective of the local flexibility allocation problem. | Reducible-generator feasibility constraints in local allocation. | SESP scheduling of local flexible resources for the operation day. | SESP-operated local flexibility market serving DSO power-quality requirements. | Service scope of the presented local flexibility market. | Shiftable-profile load feasibility in local allocation. | Upward-regulation constraints in the local flexibility allocation problem.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-001","v141-b-g01-ev-004","v141-b-g01-ev-006","v141-b-g01-ev-007","v141-b-g01-ev-010","v141-b-g01-ev-013","v141-b-g02-ev05","v141-b-g02-ev10","v141-b-g02-ev11","v141-b-g02-ev13","v141-b-g02-ev15","v141-b-g02-ev20","v141-b-g02-ev21","v141-b-g02-ev22","v141-b-g02-ev23","v141-b-g02-ev25","v141-b-g02-ev29","v141-b-g02-ev33","v141-b-g02-ev34","v141-b-g02-ev36","v141-b-g02-ev37","v141-b-g03-E13","v141-b-g03-E15","v141-b-g04-e03"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C001","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C002","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C003","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C004"],"decision_anchor":"clearing.local","source_rule_sha256":"13aaf9ab97f39a93298400dacbf1f3833b654760ae93a47ef02ed6c7d66f1361"},{"id":"21-dso_flexibility_optimization::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"The SESP, acting as aggregator, receives DSO flexibility requests specifying minimum active-energy variations relative to the forecast baseline, without knowing grid-status information. Scope: DSO upward- and downward-regulation requests in the SESP-operated local flexibility market. The SESP's coordination of corrective actions must give DSO needs maximum priority to avoid over-voltages or transformer over-loads. Scope: SESP coordination of corrective actions in the local flexibility market. Condition: During a DSO-designated yellow-light grid situation. The SESP may send direct control signals overriding local household energy-management decisions. Scope: SESP control authority over local household resource decisions. Condition: During a grid-constrained yellow-light situation. The SESP's forecast must have DSO approval before it is used as the baseline scenario. Scope: Use of SESP forecasts as the flexibility-market baseline. Condition: When a consumption or generation forecast for a flexible asset is to be used as the baseline scenario.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"DSO upward- and downward-regulation requests in the SESP-operated local flexibility market. | SESP control authority over local household resource decisions. | SESP coordination of corrective actions in the local flexibility market. | Use of SESP forecasts as the flexibility-market baseline.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-001","v141-b-g01-ev-003","v141-b-g01-ev-004","v141-b-g01-ev-011","v141-b-g01-ev-014","v141-b-g02-ev33"]},"constraint_refs":["21-dso_flexibility_optimization::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"f0a3f24e00e9c27d1e767402691fddd0233d7645925a90b115075bfc3ea2381f"}],"constraints":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The requested quantity specifies the minimum required active-energy variation relative to the forecasted baseline. Positive quantities denote upward regulation and negative quantities denote downward regulation; the per-period request is expressed in kW h/period. Scope: DSO upward and downward regulation requests in the SESP-operated local flexibility market, for each requested period.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-ev33","v141-b-g04-e01"],"ref":"21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g04-e01","location":{"location_id":"src-58f2111926-p12-c1r3__v141-a-M01-clearing","page":12,"printed_page":null,"section":null,"anchor_text":"The integration of DER into the distribution grids can lead to th technical issues aﬀecting the powe","equation_id":null,"figure_id":null,"table_id":"Table A.2/Table A.3","image_ref":"pages/page-12.png","occurrence_role":"definition"},"source_text":"Table A.2\nSets and subsets.\nT Set of periods, indexed by t\nT^{+} Subset of periods with DSO requests for upward regulation\nT^{-} Subset of periods with DSO requests for downward regulation\nK Set of non-buffered flexible loads, indexed by k\nK^{CD} Subset of flexible load units of type curtailable disconnectable\nK^{SP} Subset of flexible load units of type shiftable profile\nC Set of shiftable load periods, indexed by c. It depends on each k\nG Set of flexible distributed generators, indexed by g\nG^{r} Subset of reducible distributed generators\nG^{d} Subset of disconnectable distributed generators\nB Set of storage units, indexed by b\n\nTable A.3\nDSO parameter.\nD^{DSO}_{t} DSO request in the local flexibility market during period t [kW h/period]"}]},{"constraint_id":"v141-c-R002-C002","kind":"mathematical","role":"core","statement":"For every period t in the period set T, the DSO request D_t^{DSO} is a real-valued request measured in kWh/period, defined as the minimum required active-energy variation relative to the forecasted baseline; positive values are upward-regulation requests and negative values are downward-regulation requests. Equivalently, the upward-request periods satisfy T^{+}={t in T: D_t^{DSO}>0} and the downward-request periods satisfy T^{-}={t in T: D_t^{DSO}\u003c0}.","expression":"\\forall t\\in T:\\; D_t^{DSO}\\in\\mathbb{R}\\ \\text{(kWh/period)};\\quad T^{+}=\\{t\\in T:D_t^{DSO}>0\\};\\quad T^{-}=\\{t\\in T:D_t^{DSO}\u003c0\\}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":["v141-c-R002-P001"],"evidence_ids":["v141-b-g02-ev33","v141-b-g02-ev34","v141-b-g04-e01"],"ref":"21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C002","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g02-ev34","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17), Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons."},{"evidence_id":"v141-b-g04-e01","location":{"location_id":"src-58f2111926-p12-c1r3__v141-a-M01-clearing","page":12,"printed_page":null,"section":null,"anchor_text":"The integration of DER into the distribution grids can lead to th technical issues aﬀecting the powe","equation_id":null,"figure_id":null,"table_id":"Table A.2/Table A.3","image_ref":"pages/page-12.png","occurrence_role":"definition"},"source_text":"Table A.2\nSets and subsets.\nT Set of periods, indexed by t\nT^{+} Subset of periods with DSO requests for upward regulation\nT^{-} Subset of periods with DSO requests for downward regulation\nK Set of non-buffered flexible loads, indexed by k\nK^{CD} Subset of flexible load units of type curtailable disconnectable\nK^{SP} Subset of flexible load units of type shiftable profile\nC Set of shiftable load periods, indexed by c. It depends on each k\nG Set of flexible distributed generators, indexed by g\nG^{r} Subset of reducible distributed generators\nG^{d} Subset of disconnectable distributed generators\nB Set of storage units, indexed by b\n\nTable A.3\nDSO parameter.\nD^{DSO}_{t} DSO request in the local flexibility market during period t [kW h/period]"}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The DSO's requested flexibility supplies the input for determining local resource allocations over the operation day. Scope: SESP scheduling of local flexible resources for the operation day.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-006","v141-b-g02-ev33"],"ref":"21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-ev-006","location":{"location_id":"src-58f2111926-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"be In order to run these markets, local traders need the SESP Platform for or sending information, t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The flexibility market is executed in hours ahead time frames and its time schedule is shown in the Fig. 2. At the end of the day-before the operation, the DSO determines the flexibility need for the entire operation day. Based on the DSO request, the SESP can schedule flexible resources optimally considering the entire operation day. In the EMPOWER Project, the LFM is executed at 11 p.m. and the period unit is quarter hour."},{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."}]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"The requested upward active-energy variation imposes a minimum on the net upward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Upward-regulation constraints in the local flexibility allocation problem. Condition: During upward-regulation periods with a positive DSO request.","expression":"\\sum_{b\\in B}\\sigma_{b,t}^{out} + \\sum_{k\\in K^{CD}} W_{k,t}^{CD}\\,(\\delta_{k,t}^{start}+\\delta_{k,t}^{run}) + \\sum_{k\\in K^{SP}} (W_{k,t}^{SP}-\\omega_{k,t}) - \\sum_{g\\in G^r}\\chi_{g,t}^{Gr} - \\sum_{g\\in G^d}\\chi_{g,t}^{Gd} - \\sum_{b\\in B}\\sigma_{b,t}^{in} \\ge D_t^{DSO},\\quad \\forall t\\in T^{+}","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["var_sigma_out","var_delta_start","var_delta_run","var_omega","var_chi_gr","var_chi_gd","var_sigma_in"],"parameter_refs":["par_w_cd","par_w_sp","par_dso_request"],"evidence_ids":["v141-b-g02-ev33","v141-b-g02-ev34","v141-b-g02-ev35"],"ref":"21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C002","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g02-ev34","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17), Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons."},{"evidence_id":"v141-b-g02-ev35","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"∑b ∈ B σbout,t + ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t )+ ∑k ∈ K SP (WkSP,t −ωk ,t )−∑g ∈ G r χ gGr,t − ∑g ∈ G d χ gGd,t −∑b ∈ B σbin,t ⩾ DtDSO      ∀ t ∈ T +  (17)"}]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"The requested downward active-energy variation imposes a minimum on the magnitude of net downward regulation allocated relative to the forecasted baseline; contributions opposing the request remain included in the constraint. Scope: Downward-regulation constraints in the local flexibility allocation problem. Condition: During downward-regulation periods with a negative DSO request.","expression":"\\sum_{g\\in G^r}\\chi_{g,t}^{Gr} + \\sum_{g\\in G^d}\\chi_{g,t}^{Gd} + \\sum_{b\\in B}\\sigma_{b,t}^{in} + \\sum_{k\\in K^{SP}} (\\omega_{k,t}-W_{k,t}^{SP}) - \\sum_{b\\in B}\\sigma_{b,t}^{out} - \\sum_{k\\in K^{CD}} W_{k,t}^{CD}\\,(\\delta_{k,t}^{start}+\\delta_{k,t}^{run}) \\ge -D_t^{DSO},\\quad \\forall t\\in T^{-}","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["var_chi_gr","var_chi_gd","var_sigma_in","var_omega","var_sigma_out","var_delta_start","var_delta_run"],"parameter_refs":["par_w_cd","par_w_sp","par_dso_request"],"evidence_ids":["v141-b-g02-ev33","v141-b-g02-ev34","v141-b-g02-ev36"],"ref":"21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C003","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."},{"evidence_id":"v141-b-g02-ev34","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (17), Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Eqs. (17) and (18) are constraints that ensure that ﬂexible resources comply with the DSO upward and downward regulation request re-spectively. All ﬂexibility resources are included in both equations be-cause they can be in favour or against the request.\nDuring up-regulation periods (t ∈ T + ) deﬁned as positive DSO re-quests ( DtDSO > 0 ), controllable resources are batteries delivering active energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable loads  (WkSP,t −ωk,t ).  Additionally, down-regulation  resources  like  re-ducible and disconnectable generators (χ gGr,t χ, gGd,t ) and batteries storing energy (σbin,t ) are included in the up-regulation constraint to include the possibility of discharging batteries for further needs or disconnecting generators for other reasons."},{"evidence_id":"v141-b-g02-ev36","location":{"location_id":"src-58f2111926-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":"energy (σbout,t ), disconnectable loads (W kCD,t ·(δkstart,t + δkrun,t ) ), and shiftable od SP load","equation_id":"Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"For each downward regulation period (t ∈ T − ), deﬁned as negative request ( DtDSO \u003c 0 ), the upward and downward ﬂexibility resources have negative and positive sign respectively in Eq. (18).\n∑g ∈ G r χ gGr,t + ∑g ∈ G d χ gGd,t + ∑b ∈ B σbin,t + ∑k ∈ K SP (ωk ,t −WkSP,t )−∑b ∈ B σbout,t − ∑k ∈ K CD W kCD,t ·(δkstart,t + δkrun,t ) ⩾−DtDSO      ∀ t ∈ T −  (18)"}]},{"constraint_id":"v141-c-R003-C004","kind":"procedural","role":"core","statement":"The DSO sends its flexibility needs before the SESP executes the daily local allocation algorithm. Scope: Daily allocation sequence described for the case study.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E13"],"ref":"21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C004","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-58f2111926-p10-c1r3__v141-a-M01-clearing","page":10,"printed_page":null,"section":"5.1 Scenario description","anchor_text":"proﬁle (W k ,t + Wk ,t ) with a maximum demand of 11.15 kW h during m period 48. Generation forecast","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"example"},"source_text":"The DDSO is the DSO request for the operation day. In the case study, the available flexibility is larger than the DSO need for all periods. Therefore, SESP has to execute the LFM to allocate the cheapest flexible resources considering the problem constraints. If the SESP has not enough resources, it cannot attend the DSO request completely. ... the time horizon is one day. The SESP algorithm is executed once per day before the operation day begins. Previously, the DSO has sent its flexibility needs."}]},{"constraint_id":"v141-c-R004-C001","kind":"procedural","role":"core","statement":"The SESP, acting as aggregator, receives DSO flexibility requests specifying minimum active-energy variations relative to the forecast baseline, without knowing grid-status information. Scope: DSO upward- and downward-regulation requests in the SESP-operated local flexibility market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-001","v141-b-g01-ev-003","v141-b-g02-ev33"],"ref":"21-dso_flexibility_optimization::v141-c-R004::v141-c-R004-C001","source_rule_id":"v141-c-R004","evidence":[{"evidence_id":"v141-b-g01-ev-001","location":{"location_id":"src-58f2111926-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"be In order to run these markets, local traders need the SESP Platform for or sending information, t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"A local flexibility market (LFM) is an electricity trading platform to sell and buy flexibility in geographically limited areas like neighbourhoods and small towns. The SESP is the local market platform provider and community aggregator (AGR). At the same time, the SESP is a BRP from the regulatory point of view because it bids in wholesale markets. In order to run these markets, local traders need the SESP Platform for sending information, trading for flexibility, and scheduling actions."},{"evidence_id":"v141-b-g01-ev-003","location":{"location_id":"src-58f2111926-p02-c2r4__v141-a-M01-coordination","page":2,"printed_page":"882","section":"2.1. Centralized local flexibility market approaches","anchor_text":"on same distribution transformer have to be members of the same BRP and diﬀerent BRP could not be in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"In contrast  in  this work, AGR receives DSO requests without knowing grid status information to solve grid congestion problems in the daily basis. In order to attend its demands, AGR controls flexible assets using a market-based methodology."},{"evidence_id":"v141-b-g02-ev33","location":{"location_id":"src-58f2111926-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":"888","section":"4.5. DSO request constraints","anchor_text":", nd Tkend,c − (V kend,c − Vkstart,c ) me ρk ,c = ∑ γk ,t · t ∀ k ∈ K SP ,∀ c ∈ C (k ) t = Tkstart,c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Finally, DSO constraints represent the request for fulﬁlling upward and downward regulation. These constraints are deﬁned as the minimum required amount of active energy variation with respect to the forecasted baseline scenario and are denoted as DtDSO. Positives and negative values of DtDSO mean upward and downward regulation re-spectively."}]}],"variables":[{"variable_id":"var_chi_gr","symbol":"\\chi_{g,t}^{Gr}","meaning":"Total amount of electricity generation curtailed of the reducible generator unit g during period t.","kind":"operational","domain":"nonnegative real energy curtailed; upper-bounded by F_{g,t}^{Gr} in Eq. (2)","unit":"kWh","indices":["g ∈ G^r","t ∈ T"],"evidence_ids":["v141-b-g02-ev10","v141-b-g02-ev11","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_chi_gr"},{"variable_id":"var_chi_gd","symbol":"\\chi_{g,t}^{Gd}","meaning":"Total amount of electricity generation curtailed of the disconnectable generator unit g during period t.","kind":"operational","domain":"nonnegative real energy curtailed; defined by Eq. (3) when \\delta_{g,t}^{G}=1","unit":"kWh","indices":["g ∈ G^d","t ∈ T"],"evidence_ids":["v141-b-g02-ev10","v141-b-g02-ev11","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_chi_gd"},{"variable_id":"var_sigma_in","symbol":"\\sigma_{b,t}^{in}","meaning":"Energy charged by the storage unit b during period t.","kind":"operational","domain":"real-valued energy charged; bounded above by Q_b^{in} in Eq. (5); no explicit lower bound printed","unit":"kWh","indices":["b ∈ B","t ∈ T"],"evidence_ids":["v141-b-g02-ev13","v141-b-g02-ev14","v141-b-g02-ev15","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_sigma_in"},{"variable_id":"var_sigma_out","symbol":"\\sigma_{b,t}^{out}","meaning":"Energy discharged by the storage unit b during period t.","kind":"operational","domain":"real-valued energy discharged; bounded above by Q_b^{out} in Eq. (6); no explicit lower bound printed","unit":"kWh","indices":["b ∈ B","t ∈ T"],"evidence_ids":["v141-b-g02-ev13","v141-b-g02-ev14","v141-b-g02-ev15","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_sigma_out"},{"variable_id":"var_delta_start","symbol":"\\delta_{k,t}^{start}","meaning":"Binary variable equal to 1 if curtailment of the disconnectable load unit k starts during period t, else 0.","kind":"operational","domain":"{0,1}","unit":null,"indices":["k ∈ K^CD","t ∈ T"],"evidence_ids":["v141-b-g02-ev18","v141-b-g02-ev19","v141-b-g02-ev20","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_delta_start"},{"variable_id":"var_delta_run","symbol":"\\delta_{k,t}^{run}","meaning":"Binary variable equal to 1 if curtailment of the disconnectable load unit k is running in time period t, else 0.","kind":"operational","domain":"{0,1}","unit":null,"indices":["k ∈ K^CD","t ∈ T"],"evidence_ids":["v141-b-g02-ev18","v141-b-g02-ev19","v141-b-g02-ev20","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_delta_run"},{"variable_id":"var_omega","symbol":"\\omega_{k,t}","meaning":"Delivered energy to the shiftable load unit k during period t.","kind":"operational","domain":"real-valued delivered energy; no explicit bound printed","unit":"kWh","indices":["k ∈ K^SP","t ∈ T"],"evidence_ids":["v141-b-g02-ev25","v141-b-g02-ev30","v141-b-g04-e06"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::x::var_omega"}],"parameters":[{"parameter_id":"v141-c-R002-P001","symbol":"D_t^{DSO}","meaning":"DSO request in the local flexibility market during period t: the minimum required active-energy variation with respect to the forecasted baseline, expressed in kWh/period. Positive values denote upward regulation and negative values denote downward regulation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh/period","indices":["t"],"evidence_ids":["v141-b-g02-ev33","v141-b-g04-e01"],"source_rule_id":"v141-c-R002","declaration_ref":"21-dso_flexibility_optimization::v141-c-R002::theta::v141-c-R002-P001"},{"parameter_id":"par_dso_request","symbol":"D_t^{DSO}","meaning":"DSO request in the local flexibility market during period t, expressed as minimum active-energy variation relative to the forecasted baseline.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh/period","indices":["t ∈ T"],"evidence_ids":["v141-b-g02-ev33","v141-b-g04-e01"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::theta::par_dso_request"},{"parameter_id":"par_w_cd","symbol":"W_{k,t}^{CD}","meaning":"Curtailable load consumption forecast for the load unit k during period t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["k ∈ K^CD","t ∈ T"],"evidence_ids":["v141-b-g02-ev34","v141-b-g03-E29","v141-b-g04-e05"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::theta::par_w_cd"},{"parameter_id":"par_w_sp","symbol":"W_{k,t}^{SP}","meaning":"Shiftable load consumption forecast for the load unit k during period t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["k ∈ K^SP","t ∈ T"],"evidence_ids":["v141-b-g02-ev25","v141-b-g02-ev30","v141-b-g04-e05"],"source_rule_id":"v141-c-R003","declaration_ref":"21-dso_flexibility_optimization::v141-c-R003::theta::par_w_sp"}]}],"source_definitions":[{"unit_id":"21-dso_flexibility_optimization::v141-a-M01::bidding.demand","stage":"L3","subtype":"signed_minimum_regulation_request","projection_status":"clear","target_definition":"Before the daily configuration algorithm is executed, the DSO submits to SESP the time-differentiated demand D_t^{DSO}∈ℝ, representing the active-power quantity change relative to the minimum requirement of the forecast baseline, in kWh/period; positive values request upward adjustment and negative values request downward adjustment, determining T^{+} and T^{-}, respectively.","form_kind":"mathematical","identity_fields":["Object: time-differentiated flexibility service demand","Core relation: submit a minimum active-power quantity change requirement relative to the forecast baseline","Output: the direction-signed demand parameter D_t^{DSO} and the corresponding set of request periods"],"variation_fields":["Requesting party DSO, receiving party SESP","The request covers the entire operating day and is sent before daily configuration","A positive sign indicates upward adjustment; a negative sign indicates downward adjustment","When receiving the request, SESP does not have grid state information"],"constraint_refs":["21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C001","21-dso_flexibility_optimization::v141-c-R002::v141-c-R002-C002","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C001","21-dso_flexibility_optimization::v141-c-R003::v141-c-R003-C004","21-dso_flexibility_optimization::v141-c-R004::v141-c-R004-C001"],"paper_id":"21-dso_flexibility_optimization","mechanism_id":"v141-a-M01","function":"bidding.demand","template_code":"SRP"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/128"});
